StructuredTextModel.Text:
IF Inp_TilgjengligAuto_Regulator AND Inp_TilgjengligAuto_Ventil THEN 
	
	
	IF Inp_GrenseTrinnNed < Inp_Pådrag_Fra_PID AND Inp_VarmepumpeDiff1 <  Inp_Grense_VP_Diff_TrinnNed AND Inp_VarmepumpeDiff2 <  Inp_Grense_VP_Diff_TrinnNed AND SecToTime(In:=TrinnIntervall) > TrinnIntervall_Timer THEN
		Inc(InOut:=TrinnTellerOpp);
		TrinnIntervall_Timer := T#0s;
	ELSIF
		Inp_GrenseTrinnOpp > Inp_Pådrag_Fra_PID AND Inp_VarmepumpeDiff1> Inp_GrenseTrinnOpp AND Inp_VarmepumpeDiff2 > Inp_Grense_VP_Diff_TrinnOpp AND SecToTime(In:=TrinnIntervall) > TrinnIntervall_Timer THEN
		Inc(InOut:=TrinnTellerOpp);
		TrinnIntervall_Timer := T#0s;
	END_IF;  
	
ELSE
	Output := 0; 
END_IF;
	
	
	IF TrinnTellerOpp >= 1 THEN 
		Output := Output + Inp_PådragØkning_TrinnOpp;
	END_IF;
	
	
		IF TrinnTellerNed >= 1 THEN 
		Output := Output + Inp_PådragReduksjon_TrinnNed;
	END_IF;	
	
	
	
	
	TrinnIntervall_Timer:= (ADD_TIME(In1:=TrinnIntervall_Timer, In2:=GetMyTaskInterval()));
